// Python 원본: scripts/keyword_groups.py::active_keyword_groups() +
// scripts/run_news_collection.py::build_group_query() — 로직을 그대로 이식했다.
// 실제 n8n 인스턴스로 아직 검증되지 않았다.
const rows = $input.all().map(item => item.json);
const items = [];
for (const row of rows) {
  if (String(row.enabled).toUpperCase() !== 'TRUE') continue;
  const includeKeywords = String(row.include_keywords || '')
    .split(',').map(s => s.trim()).filter(Boolean);
  const excludeKeywords = String(row.exclude_keywords || '')
    .split(',').map(s => s.trim()).filter(Boolean);
  const sources = String(row.sources || '')
    .split(',').map(s => s.trim()).filter(Boolean);
  const query = includeKeywords
    .map(kw => kw.includes(' ') ? '"' + kw + '"' : kw)
    .join(' OR ');
  for (const sourceId of sources) {
    items.push({
      json: {
        group_id: row.group_id,
        topic_id: row.topic_id,
        group_name: row.group_name,
        include_keywords: includeKeywords,
        exclude_keywords: excludeKeywords,
        group_ai_instructions: row.ai_instructions || '',
        source_id: sourceId,
        query: query,
      },
    });
  }
}
return items;

// n8n의 pairedItem 추적 기능으로 상류 'Config Load' 노드의 원본 컨텍스트(group_id 등)를
// 되찾는다 — HTTP Request/XML 노드는 입력 1건당 출력 1건이라 pairedItem이 그대로
// 이어진다고 가정한다(공식 n8n itemMatching() 패턴, 실제 인스턴스 미검증 — 알려진 한계).
function getContext(entry) {
  const paired = Array.isArray(entry.pairedItem) ? entry.pairedItem[0] : entry.pairedItem;
  const idx = paired && typeof paired === 'object' ? paired.item : paired;
  return $('Config Load').itemMatching(idx).json;
}

// n8n XML 노드가 만든 {rss: {channel: {item: [...]}}} 구조를 RawArticle 형태로 편다.
// Python 원본: scripts/adapters/google_rss_adapter.py::parse_feed()
const out = [];
for (const entry of $input.all()) {
  const ctx = getContext(entry);
  const channel = entry.json.rss && entry.json.rss.channel;
  let items = (channel && channel.item) || [];
  if (!Array.isArray(items)) items = [items];
  for (const it of items) {
    out.push({
      json: {
        ...ctx,
        title_original: (it.title || '').toString().trim(),
        source_url: it.link || '',
        published_at: it.pubDate || null,
        language: ctx.source_id === 'SRC-0002' ? 'ko' : 'en',
      },
    });
  }
}
return out;

// n8n의 pairedItem 추적 기능으로 상류 'Config Load' 노드의 원본 컨텍스트(group_id 등)를
