// Python 원본: scripts/adapters/naver_news_adapter.py::parse_response()/_clean_naver_text()
function cleanNaverText(text) {
  return String(text || '')
    .replace(/<[^>]+>/g, '')
    .replace(/&quot;/g, '"').replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'")
    .trim();
}
const out = [];
for (const entry of $input.all()) {
  const ctx = getContext(entry);
  const items = (entry.json.items) || [];
  for (const it of items) {
    out.push({
      json: {
        ...ctx,
        title_original: cleanNaverText(it.title),
        source_url: it.originallink || it.link || '',
        published_at: it.pubDate || null,
        language: 'ko',
      },
    });
  }
}
return out;

// Python 원본: scripts/pipeline/normalize.py + scripts/pipeline/rule_filter.py
// (passes_rule_filter_group). 정확한 ART-YYYYMMDD-NNNN 순번 채번(Python의 next_id())은
// n8n 실행 컨텍스트에서 재현하지 않고 타임스탬프 기반 근사 ID를 쓴다(알려진 한계 —
// config/technical_debt_registry.yaml 참고, 실제 순번은 Python 배치 실행 결과가 기준).
function passesRuleFilter(title, includeKeywords, excludeKeywords) {
  const t = title.toLowerCase();
  if (excludeKeywords.some(kw => t.includes(kw.toLowerCase()))) return false;
  if (includeKeywords.length === 0) return true;
  return includeKeywords.some(kw => t.includes(kw.toLowerCase()));
}
const seen = new Set();
const out = [];
let i = 0;
for (const entry of $input.all()) {
  const j = entry.json;
  if (!j.source_url || seen.has(j.source_url)) continue;
  seen.add(j.source_url);
  i += 1;
  const matched = passesRuleFilter(
    j.title_original || '', j.include_keywords || [], j.exclude_keywords || []
  );
  out.push({
    json: {
      ...j,
      article_id: 'ART-' + $now.toFormat('yyyyMMdd') + '-' + String(i).padStart(4, '0'),
      status: matched ? 'collected' : 'rejected',
      matched: matched,
    },
  });
}
return out;

// Python scripts/providers/claude_provider.py::_strip_markdown_json_fence()와 동일한
// 로직 — Claude가 JSON을 ```json ... ``` 코드펜스로 감싸 응답하는 경우가 실측으로
// 확인됐다(Round 13 이어서, 2026-08-08).
function stripMarkdownFence(text) {
  const trimmed = text.trim();
  const m = trimmed.match(/^```(?:json)?\s*\n([\s\S]*)\n```$/);
  return m ? m[1] : text;
}
function parseClaudeJson(text) {
  try { return JSON.parse(text); }
  catch (e) { return JSON.parse(stripMarkdownFence(text)); }
}

// 원본 article 필드는 '정규화·중복제거·Rule Filter' 노드의 pairedItem으로 되찾는다
// (Claude Relevance HTTP 노드가 $json을 API 응답으로 덮어써서 사라졌기 때문).
function getArticle(entry) {
  const paired = Array.isArray(entry.pairedItem) ? entry.pairedItem[0] : entry.pairedItem;
  const idx = paired && typeof paired === 'object' ? paired.item : paired;
  return $('정규화·중복제거·Rule Filter').itemMatching(idx).json;
}
const out = [];
for (const entry of $input.all()) {
  const text = entry.json.content && entry.json.content[0] && entry.json.content[0].text;
  const parsed = parseClaudeJson(text || '{}');
  out.push({ json: { ...getArticle(entry), ...parsed } });
}
return out;

// Python scripts/providers/claude_provider.py::_strip_markdown_json_fence()와 동일한
// 로직 — Claude가 JSON을 ```json ... ``` 코드펜스로 감싸 응답하는 경우가 실측으로
// 확인됐다(Round 13 이어서, 2026-08-08).
function stripMarkdownFence(text) {
  const trimmed = text.trim();
  const m = trimmed.match(/^```(?:json)?\s*\n([\s\S]*)\n```$/);
  return m ? m[1] : text;
}
function parseClaudeJson(text) {
  try { return JSON.parse(text); }
  catch (e) { return JSON.parse(stripMarkdownFence(text)); }
}

// 원본 article+relevance 필드는 'Relevance 응답 파싱' 노드의 pairedItem으로 되찾는다.
function getArticle(entry) {
  const paired = Array.isArray(entry.pairedItem) ? entry.pairedItem[0] : entry.pairedItem;
  const idx = paired && typeof paired === 'object' ? paired.item : paired;
  return $('Relevance 응답 파싱').itemMatching(idx).json;
}
const REQUIRED = ['facts', 'significance', 'importance_level', 'intelligence_categories',
  'lx_impact', 'actions', 'confidence', 'evidence', 'unknowns'];
const out = [];
for (const entry of $input.all()) {
  const text = entry.json.content && entry.json.content[0] && entry.json.content[0].text;
  let parsed;
  try { parsed = parseClaudeJson(text || '{}'); } catch (e) { parsed = null; }
  const missing = !parsed || REQUIRED.some(k => !(k in parsed));
  out.push({
    json: {
      ...getArticle(entry),
      ...(parsed || {}),
      status: missing ? 'needs_review' : 'analyzed',
    },
  });
}
return out;

// Python 원본: scripts/pipeline/build_digest.py (select_digest_records/build_digest_body).
const ALERT_LEVELS = ['긴급', '중요'];
const all = ($input.first().json.records || []).map(r => r.json || r);
const alertRecords = all.filter(r => ALERT_LEVELS.includes(r.importance_level));
alertRecords.sort((a, b) => ALERT_LEVELS.indexOf(a.importance_level) - ALERT_LEVELS.indexOf(b.importance_level));
const MAX_ITEMS = 3; // config/notification.yaml email.max_highlighted_changes와 동일 값
let body;
if (alertRecords.length === 0) {
  body = '오늘 새로 발송할 만큼 중요한 변화는 없다.';
} else {
  const lines = ['오늘의 핵심 변화 ' + Math.min(alertRecords.length, MAX_ITEMS) + '건:'];
  for (const r of alertRecords.slice(0, MAX_ITEMS)) {
    lines.push('\n[' + r.importance_level + '] ' + (r.title_original || '') +
      '\n- 시사점: ' + ((r.lx_impact || []).join('; ') || '(LX 영향 근거 없음)') +
      '\n- 제언: ' + ((r.actions || []).join('; ') || '(제언 없음)'));
  }
  body = lines.join('\n');
}
const subject = alertRecords.length === 0
  ? '미국 엔지니어드스톤 리스크 알리미 — 신규 주요 변화 없음'
  : '미국 엔지니어드스톤 리스크 알리미 — 신규 ' + alertRecords.length + '건';
return [{ json: { subject: subject, body: body, has_alert: alertRecords.length > 0 } }];
